  if (previous_callout == NULL ||
      previous_callout != parsed_pattern - 4 ||
      previous_callout[3] != 255)
    {
    previous_callout = parsed_pattern;
    parsed_pattern += 4;
    previous_callout[0] = META_CALLOUT_NUMBER;
